        if rate < fa.stages[stage].Threshold*0.1 && rate > 0 {
            // 转化率异常低（可能是僵尸流量）
            signals = append(signals, FraudSignal{
                Type:      "low_conversion_rate",
                Stage:     stage,
                Severity:  "medium",
                Score:     0.6,
            })
        }
    }

    return signals
}
