## 第二部分：设备指纹

### 2.1 设备指纹生成

```go
package fingerprint

import (
    "crypto/sha256"
    "fmt"
    "net"
    "strings"
)

type DeviceInfo struct {
    UserAgent   string
    ScreenSize  string
    Language    string
    TimeZone    string
    CanvasHash  string
    WebglHash   string
    AudioHash   string
    HardwareConcurency int
    Platform    string
    DoNotTrack  bool
    MaxTouchPoints int
    DeviceMemory int
}

func GenerateFingerprint(info DeviceInfo) string {
    // 1. 收集设备特征
    features := []string{
        info.UserAgent,
        info.ScreenSize,
        info.Language,
        info.TimeZone,
        info.CanvasHash,
        info.WebglHash,
        info.AudioHash,
        fmt.Sprintf("%d", info.HardwareConcurrency),
        info.Platform,
        fmt.Sprintf("%v", info.DoNotTrack),
        fmt.Sprintf("%d", info.MaxTouchPoints),
        fmt.Sprintf("%d", info.DeviceMemory),
    }

    // 2. 拼接特征
    fingerprint := strings.Join(features, "|")

    // 3. SHA256 哈希
    hash := sha256.Sum256([]byte(fingerprint))

    return fmt.Sprintf("%x", hash[:16])
}
```

### 2.2 IP 信誉评分

```go
type IPReputation struct {
    reputationScores map[string]float64
}

func (ir *IPReputation) GetScore(ip string) float64 {
    if score, ok := ir.reputationScores[ip]; ok {
        return score
    }

    // 计算 IP 信誉
    score := ir.calculateIPReputation(ip)
    ir.reputationScores[ip] = score

    return score
}

func (ir *IPReputation) calculateIPReputation(ip string) float64 {
    score := 1.0 // 默认满分

    // 1. 检查是否为数据中心 IP
    if ir.isDatacenterIP(ip) {
        score -= 0.3
    }

    // 2. 检查是否为代理/VPN
    if ir.isProxyIP(ip) {
        score -= 0.4
    }

    // 3. 检查 Tor 节点
    if ir.isTorNode(ip) {
        score -= 0.5
    }

    // 4. 检查 IP 历史
    if ir.hasSuspiciousHistory(ip) {
        score -= 0.2
    }

    return math.Max(0, score)
}
```

