### 3.2 设备指纹

```go
package fingerprint

import (
    "crypto/sha256"
    "fmt"
    "hash/crc32"
    "strings"
)

type DeviceInfo struct {
    UserAgent        string
    ScreenSize       string
    Language         string
    TimeZone         string
    CanvasHash       string
    WebglHash        string
    AudioHash        string
    HardwareConcurency int
    Platform         string
    DoNotTrack       bool
    MaxTouchPoints   int
    DeviceMemory     int
}

func GenerateFingerprint(info DeviceInfo) string {
    // 1. 收集设备特征
    features := []string{
        info.UserAgent,
        info.ScreenSize,
        info.Language,
        info.TimeZone,
        info.CanvasHash,
        info.WebglHash,
        info.AudioHash,
        fmt.Sprintf("%d", info.HardwareConcurrency),
        info.Platform,
        fmt.Sprintf("%v", info.DoNotTrack),
        fmt.Sprintf("%d", info.MaxTouchPoints),
        fmt.Sprintf("%d", info.DeviceMemory),
    }

    // 2. 拼接特征
    fingerprint := strings.Join(features, "|")

    // 3. SHA256 哈希
    hash := sha256.Sum256([]byte(fingerprint))

    return fmt.Sprintf("%x", hash[:16])
}

// Canvas Hash 生成
func GenerateCanvasHash(canvas *html.CanvasElement) string {
    ctx := canvas.getContext("2d")

    // 绘制测试图形
    ctx.fillRect(0, 0, 100, 100)
    ctx.fillStyle = "#f60"
    ctx.fillRect(10, 10, 50, 50)
    ctx.fillStyle = "rgba(126, 146, 198, 0.5)"
    ctx.fillText("Test", 2, 15)

    // 获取渲染结果
    dataURL := canvas.toDataURL()

    // CRC32 哈希
    return fmt.Sprintf("%x", crc32.ChecksumIEEE([]byte(dataURL)))
}
